import ttsSpeakSettles from './tts-speak-settles.mjs';
import sttTerminalHandlers from './stt-terminal-handlers.mjs';
import micCaptureReleased from './mic-capture-released.mjs';
import micConstraintsNotScreenCapture from './mic-constraints-not-screen-capture.mjs';
import sttErrorMapHasDefault from './stt-error-map-has-default.mjs';
import sttInterimResultsGated from './stt-interim-results-gated.mjs';

// browser-speech — driving the browser's speech APIs (SpeechRecognition /
// webkitSpeechRecognition, chrome.tts, speechSynthesis, and the getUserMedia
// capture behind them).
//
// Every rule here judges a browser API contract, not a product decision: it is
// written to hold in ANY voice-driven web app, and its scan is repo-shape
// agnostic (see lib.mjs `isSource`) so it cannot pass vacuously green somewhere
// laid out differently. It lives locally only because the mounted canon has no
// home for this facet yet — the chrome-extension pack covers MV3 build/runtime
// gotchas and says nothing about speech, and `node` / `github-actions` /
// `spec-driven-product` are orthogonal. Declared by hand as
// `local/browser-speech` in .claudinite-settings.json.
export default {
  id: 'browser-speech',
  ruleRoutingGuidance: {
    belongs: 'browser speech API contracts — SpeechRecognition, chrome.tts, speechSynthesis, and the getUserMedia capture behind them',
    excludes: 'MV3 build and runtime gotchas — those are chrome-extension',
  },
  marker: null,
  detect: null,
  prose: 'RULES.md',
  worldRules: [
    ttsSpeakSettles,
    sttTerminalHandlers,
    micCaptureReleased,
    micConstraintsNotScreenCapture,
    sttErrorMapHasDefault,
    sttInterimResultsGated,
  ],
};

import pageObserversDisconnected from './page-observers-disconnected.mjs';
import syntheticInputEventsBubble from './synthetic-input-events-bubble.mjs';

// host-page-adaptation — being a guest in a web app you do not own: reading its
// DOM, driving it with synthetic input, watching it change, and injecting your
// own UI into it, all against markup that can be redesigned without notice.
//
// Every rule here judges a DOM/API contract that holds for any code driving a
// third-party page — a userscript, a browser automation layer, an extension's
// content script — and its scan is repo-shape agnostic (see lib.mjs `isSource`)
// so it cannot pass vacuously green somewhere laid out differently. It lives
// locally only because the mounted canon has no home for this facet: the
// chrome-extension pack covers MV3 manifest/permission/content-script MECHANICS
// (how to get your code onto the page) and says nothing about what to do once it
// is there, and node / github-actions / chrome-extension-release /
// spec-driven-product / executable-requirements are orthogonal. Declared by hand
// as `local/host-page-adaptation` in .claudinite-settings.json.
export default {
  id: 'host-page-adaptation',
  ruleRoutingGuidance: {
    belongs: 'driving a host web app you don\'t own — its DOM, synthetic input, change watching, injected UI',
    excludes: 'how extension code reaches the page (manifest, permissions, registration) — chrome-extension; speech APIs — local/browser-speech',
  },
  marker: null,
  detect: null,
  prose: 'RULES.md',
  worldRules: [
    pageObserversDisconnected,
    syntheticInputEventsBubble,
  ],
};

